    const yy=b.y+Math.sin((b.t||0)*1.6)*6; b._drawY=yy; b._drawW=w; b._drawH=h;
    // rotor spin: derive angle from the boss clock (b.t advances each update) -> deg, pick nearest 5-deg frame
