      _drawPodFlash();
      if(b.flash>0){ const tc=xartTint(bodyKey,b.flash>0.04?'#ffffff':'#ff8a4a',0.85); if(tc) ctx.drawImage(tc,b.x-w/2,yy-h/2,w,h); }
