  if(ASSETS.has(wIcon)){ ctx.save(); ctx.shadowColor=wglow; ctx.shadowBlur=8; const dd=ASSETS.dims(wIcon), ss=Math.min(30/dd.w,24/dd.h); ASSETS.blit(wIcon,cx[4],HUDH*0.46,dd.w*ss,dd.h*ss); ctx.restore(); }
