    e._fx0=e.x; e._fy0=e.y;
    const _mv=Math.hypot(e._mvx||0,e._mvy||0);
    if(e._faceAng==null && _mv>0.12){
      /* art points UP at 0 rad, so +PI/2 converts a travel vector into its pose:
         straight down -> PI (unchanged), due east -> PI/2, due west -> -PI/2. */
      e._travelAng = Math.atan2(e._mvy, e._mvx) + Math.PI/2;
    }
    // Bank frame from real motion, not from a vx the pattern may never touch.
    let bank='c';
    const vx=(Math.abs(e.vx||0) > Math.abs(e._mvx||0)) ? (e.vx||0) : (e._mvx||0);
    if(vx<=-1.1) bank='hl'; else if(vx<=-0.35) bank='l'; else if(vx>=1.1) bank='hr'; else if(vx>=0.35) bank='r';
    let key=(st==='inta')?(k+'_intact_'+bank):(k+'_'+st+'_c');
    if(!XART.rdy(key)) key=k+'_intact_'+bank;
    if(!XART.rdy(key)) key=k+'_intact_c';
    if(!XART.rdy(key)) return false;
    const im=XART.get(key);
    const dw=e.w*2.15, dh=dw*(im.naturalHeight/im.naturalWidth);
    // DROP 0719: damage trails — smoke when damaged, fire when critical. Enemies point down-screen,
    // so the exhaust streams UP behind them (art flows down natively -> flip vertically).
    if(st!=='inta'){
      const _dk='ntr_'+(st==='crit'?'fire':'smkL')+'_'+((((performance.now()/70)|0)+(e.variant||0))%8);
      if(XART.rdy(_dk)){ const tim=XART.get(_dk), tw2=Math.max(8,dw*0.28), th2=dh*(st==='crit'?1.3:1.0);
        ctx.save(); ctx.globalAlpha=st==='crit'?0.85:0.6; ctx.translate(e.x, e.y-dh*0.35); ctx.scale(1,-1);
        ctx.drawImage(tim, -tw2/2, 0, tw2, th2); ctx.restore(); }
    }
    drawUnitShadow(e.x,e.y,dw,dh,0.26);
    ctx.save(); ctx.translate(e.x,e.y);
