    if(t){ const tc=xartTint(key,t,(t==='#ffffff'?0.85:0.55)); ctx.drawImage(tc||im,-dw/2,-dh/2,dw,dh); }
    else ctx.drawImage(im,-dw/2,-dh/2,dw,dh);
