        if(e._muz&&e._muz>0){ const mf='t_muz'+(Math.floor(e._muz*16)%2); if(ASSETS.has(mf)){ const ms=e.w*0.55; ASSETS.blit(mf,0,dh*0.32,ms,ms);} }
        // dive exhaust glow behind a committed kamikaze
