      const _mgGlow=({1:'#ffbe2a',2:'#3a8aff',3:'#5fe07a',4:'#dfe8ff',5:'#ff5a48'})[_mgLv];
      const _mgSize=(_mgLv<=2)?(16+_mgCol*3):(13+_mgCol*3);
