/* ============================================================
   ELITE ENEMIES — the pack's modular units flown as ORDINARY roster enemies.
   A boss occupies the single global boss slot, so for wave lists the unit's components are
   composited ONCE per (unit, damage state) into a cached canvas and drawn as a normal sprite.
   Damage state follows HP: clean > 60%, dam > 25%, else ruin.
   ============================================================ */
/* ============================================================
   MINI TANKS (levels 1 & 4) and SHIPS (level 3) — Mike's incoming sheets.
   Small, destructible, and they lob PELLET BALLS at you. Drawn at native size or slightly
   under so they read as emplacements rather than bosses.
   Sprites were isolated by connected-component masking, so no neighbour can bleed in.
   ============================================================ */
/* ============================================================
   SPEED BOOSTERS — Mike: chevron pads laid around level 6 (and later the rival dogfights).
   You RIDE OVER them to gain speed: on level 6 that is how you slip an incoming asteroid,
   in a dogfight it is how you close the gap. The chevron inside the frame FLASHES WHITE at
   ~7fps so the pad reads as live from across the screen.
   ============================================================ */
let speedPads=[];
const SPD_FLASH_FPS=7;
function speedPadsReset(){ speedPads=[]; }
function speedPadSpawn(x,y,dir){
  speedPads.push({x:x, y:(y!=null?y:-40), dir:dir||'up', t:0, used:false, dead:false});
}
function speedPadsUpdate(dt){
  if(!speedPads.length) return;
  for(const p of speedPads){
    if(p.dead) continue;
    p.t+=dt;
    p.y += 1.05;                                   // drifts down with the level
    if(p.y>VH+60){ p.dead=true; continue; }
    if(p.used){ p._fade=(p._fade||0)+dt; if(p._fade>0.35) p.dead=true; continue; }
    // ride over it
    if(player && !player.dead && Math.abs(player.x-p.x)<24 && Math.abs(player.y-p.y)<24){
      p.used=true;
      const D={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[p.dir]||[0,-1];
      player._boost={vx:D[0]*4.6, vy:D[1]*4.6, t:0.55};
      run.speed=Math.min(4,(run.speed||0)+1); run.speedT=Math.max(run.speedT||0, 3.0);
      if(Audio.SFX.powerup)Audio.SFX.powerup();
      floatText(p.x, p.y-14, 'BOOST', '#8fe8ff');
    }
  }
  speedPads=speedPads.filter(p=>!p.dead);
  // carry the ride-over shove
  if(player && player._boost){
    const b=player._boost; b.t-=dt;
    player.x=clamp(player.x+b.vx, 12, worldWidth()-12);
    player.y=clamp(player.y+b.vy, 30, VH-20);
    if(b.t<=0) player._boost=null;
  }
}
function speedPadsDraw(){
  if(typeof XART==='undefined'||!speedPads.length) return;
  for(const p of speedPads){
    if(p.dead) continue;
    const k='nspd_'+p.dir;
    if(!XART.rdy(k)) continue;
    const im=XART.get(k);
    const sc=p.used ? 1+(p._fade||0)*1.6 : 1;
    const w=34*sc, h=w*(im.naturalHeight/im.naturalWidth);
    ctx.save(); ctx.translate(p.x,p.y);
    ctx.globalAlpha = p.used ? Math.max(0,1-(p._fade||0)/0.35) : 1;
    ctx.drawImage(im,-w/2,-h/2,w,h);
    // the chevron flashes WHITE at ~7fps so the pad reads as live
    if(!p.used && (Math.floor(p.t*SPD_FLASH_FPS)%2)===0){
      ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=0.85;
      ctx.drawImage(im,-w/2,-h/2,w,h);
    }
    ctx.restore();
  }
}
/* ============================================================
   BUNKER TURRETS — dug-in emplacements for levels 1 and 4. They do not move: they sit on open
   ground, TRACK the player through 7 authored rotation steps, fire with a muzzle flash, and play
   a 6-frame collapse when destroyed. Terrain-aware via the same ground mask the tanks use.
   ============================================================ */
/* ============================================================
   360-DEGREE TURRETS (Mike) — sand-side emplacements on level 1. They NEVER move: they hold
   position and simply turn to face you through 24 frames at 15-degree steps, firing either a
   DUAL MACHINE-GUN BURST or a SINGLE MISSILE.
   ============================================================ */
const TUR360={
  turretMG :{art:'ntur_a', w:32,h:32, hp:24, sc:850,  mode:'mg',  fr:1.7},
  turretMSL:{art:'ntur_b', w:34,h:34, hp:30, sc:1050, mode:'msl', fr:2.4},
};
const TUR_STEPS=24, TUR_DEG=15;
function tur360Tick(e, dt){
  const D=TUR360[e._tur]; if(!D) return;
  if(e._dieT!=null){ e._dieT+=dt; if(e._dieT>0.72) e.dead=true; return; }
  // FULL 360 aim — pick the nearest 15-degree frame to the true bearing
  if(player && !player.dead){
    let deg=Math.atan2(player.y-e.y, player.x-e.x)*180/Math.PI;   // 0 = right, +down
    if(deg<0) deg+=360;
    e._aimDeg=deg;
    e._turIdx=Math.round(deg/TUR_DEG)%TUR_STEPS;
  }
  e._fire=(e._fire==null?rnd(0.9,2.0):e._fire)-dt;
  if(e._fire<=0){
    const a=((e._aimDeg||0)*Math.PI/180);
    if(D.mode==='mg'){
      // DUAL machine guns: a short burst from two barrels
      e._burst=(e._burst||0)+1;
      e._fire = (e._burst%3===0) ? D.fr*rnd(0.9,1.25)/Math.max(0.4,DIFF.eFire) : 0.10;
      const nx=-Math.sin(a), ny=Math.cos(a);                       // barrel separation, perpendicular
      for(const sgn of [-1,1]) eShootT(e.x+nx*7*sgn, e.y+ny*7*sgn, a, 2.6, 'pellet', null);
    } else {
      // SINGLE missile
      e._fire = D.fr*rnd(0.9,1.2)/Math.max(0.4,DIFF.eFire);
      if(typeof eMissile==='function') eMissile(e.x, e.y);
      else eShootT(e.x, e.y, a, 2.0, 'bolt', null);
    }
    e._muz=0.10;
  }
  if(e._muz>0) e._muz-=dt;
}
function drawTur360(e){
  if(typeof XART==='undefined') return false;
  const D=TUR360[e._tur]; if(!D) return false;
  if(e._dieT!=null){
    const fi=Math.min(5, Math.floor(e._dieT*9));
    const dk=(e._tur==='turretMG'?'nbk_r2_':'nbk_r5_')+fi;
    if(XART.rdy(dk)){
      const im=XART.get(dk), h=e.h*1.9, w=h*(im.naturalWidth/im.naturalHeight);
      ctx.save(); ctx.translate(e.x,e.y); ctx.drawImage(im,-w/2,-h/2,w,h); ctx.restore();
      return true;
    }
    return false;
  }
  // SANDBAGS STAY PUT (Mike): the base is a single static image; only the gun frame changes.
  // Both share one canvas and one pivot, so they composite with the same rect.
  const bkey=D.art+'_base', gkey=D.art+'_'+(e._turIdx||0);
  if(!XART.rdy(bkey)||!XART.rdy(gkey)) return false;
  const bim=XART.get(bkey), gim=XART.get(gkey);
  const h=e.h*2.6, w=h*(bim.naturalWidth/bim.naturalHeight);
  ctx.save(); ctx.translate(e.x,e.y);
  // e.flash tint is applied through xartTint after the draw, not a canvas filter
  ctx.drawImage(bim,-w/2,-h/2,w,h);      // sandbag emplacement — never rotates
  ctx.drawImage(gim,-w/2,-h/2,w,h);      // gun only
  ctx.restore();
  if(e._muz>0){
    const a=((e._aimDeg||0)*Math.PI/180);
    ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=clamp(e._muz/0.10,0,1);
    ctx.fillStyle='#ffd98a';
    circle(e.x+Math.cos(a)*15, e.y+Math.sin(a)*15, 4+e._muz*20);
    ctx.restore();
  }
  return true;
}
/* Place a turret on OPEN SAND near a screen edge (Mike: "level 1, in the sand on the sides"). */
const EMPLACE_CAP=4;
function _emplaceCount(){
  let n=0; for(const e of enemies){ if(!e.dead && (e._tur||e._bunker)) n++; }
  return n;
}
function turretSpawnSide(kind, side, y){
  if(_emplaceCount()>=EMPLACE_CAP) return null;   // keep the flanks readable
  const W=worldWidth();
  const inner = side<0 ? [26, W*0.28] : [W*0.72, W-26];
  for(let a=0;a<26;a++){
    const x=rnd(inner[0], inner[1]);
    if(typeof miniTerrainOK!=='function' || miniTerrainOK('ground', x, (y!=null?y:-30), 30)){
      return spawnEnemy(kind, x, (y!=null?y:-30), {});
    }
  }
  return spawnEnemy(kind, side<0? W*0.14 : W*0.86, (y!=null?y:-30), {});
}
const BUNKER_DEF={
  bunkerA:{rot:'nbk_r1', die:'nbk_r2', nrot:7, ndie:6, w:34,h:34, hp:26, sc:900,  fr:1.5},
  bunkerB:{rot:'nbk_r4', die:'nbk_r5', nrot:7, ndie:6, w:36,h:36, hp:32, sc:1100, fr:1.3},
};
function bunkerTick(e, dt){
  const D=BUNKER_DEF[e._bunker]; if(!D) return;
  if(e._dieT!=null){ e._dieT+=dt; if(e._dieT>0.72) e.dead=true; return; }
  // AIM: pick the rotation step that best points at the player
  if(player && !player.dead){
    // The player is nearly always BELOW an emplacement, so the useful arc is right -> down -> left.
    // Mapping the full circle wasted 5 of the 7 steps; this spreads them across the arc that matters.
    const ang=Math.atan2(player.y-e.y, player.x-e.x);      // ~0 (right) .. PI (left) when below
    const k=clamp(ang/Math.PI,0,1);
    e._rotIdx=clamp(Math.round(k*(D.nrot-1)),0,D.nrot-1);
  }
  e._fire=(e._fire==null?rnd(0.8,1.8):e._fire)-dt;
  if(e._fire<=0){
    e._fire=D.fr*rnd(0.85,1.2)/Math.max(0.4,DIFF.eFire);
    const a=Math.atan2((player?player.y:VH)-e.y,(player?player.x:e.x)-e.x);
    for(const off of [-0.10,0.10]) eShootT(e.x, e.y, a+off, 2.4, 'pellet', null);
    e._muz=0.11;
  }
  if(e._muz>0) e._muz-=dt;
}
function drawBunker(e){
  if(typeof XART==='undefined') return false;
  const D=BUNKER_DEF[e._bunker]; if(!D) return false;
  let key;
  if(e._dieT!=null){
    const fi=Math.min(D.ndie-1, Math.floor(e._dieT*9));
    key=D.die+'_'+fi;
  } else {
    key=D.rot+'_'+(e._rotIdx||0);
  }
  if(!XART.rdy(key)) return false;
  const im=XART.get(key);
  const h=e.h*1.9, w=h*(im.naturalWidth/im.naturalHeight);
  ctx.save(); ctx.translate(e.x,e.y);
  // e.flash tint is applied through xartTint after the draw, not a canvas filter
  ctx.drawImage(im,-w/2,-h/2,w,h);
  ctx.restore();
  // muzzle pop
  if(e._muz>0){
    ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=clamp(e._muz/0.11,0,1);
    ctx.fillStyle='#ffd98a'; circle(e.x, e.y-2, 5+e._muz*22); ctx.restore();
  }
  return true;
}
const MINI_DEF={
  // TANKS are drawn facing up, so they patrol UP/DOWN and are confined to open ground —
  // sand and light growth are fair, the dark cliffs are impassable.
  // SHIPS are drawn side-on, so they patrol LEFT/RIGHT, are scaled down to fit the ice channels,
  // and are confined to water — they cannot ride up onto the snowy rocks.
  // tag        art row  cols        w   h  hp  score  cadence scale  terrain   axis
  minitank : {row:0, cols:[7,12], w:30,h:30, hp:9,  sc:420, fr:1.6, scale:0.86, terr:'ground', axis:'v'},
  minitank2: {row:1, cols:[7,12], w:30,h:30, hp:11, sc:480, fr:1.5, scale:0.86, terr:'ground', axis:'v'},
  minitank3: {row:3, cols:[7,12], w:30,h:30, hp:13, sc:540, fr:1.4, scale:0.86, terr:'ground', axis:'v'},
  minishipA: {row:5, cols:[0,6],  w:24,h:17, hp:10, sc:460, fr:1.5, scale:0.62, terr:'water',  axis:'h'},
  minishipB: {row:6, cols:[0,6],  w:24,h:17, hp:12, sc:520, fr:1.4, scale:0.62, terr:'water',  axis:'h'},
  minishipC: {row:7, cols:[0,6],  w:26,h:18, hp:14, sc:580, fr:1.3, scale:0.64, terr:'water',  axis:'h'},
};
function miniArtKey(e){
  const D=MINI_DEF[e._mini]; if(!D) return null;
  const [c0,c1]=D.cols;
  const span=c1-c0;
  // pick the rotation step from the unit's facing so it turns rather than flipping
  const idx=c0+clamp(Math.round(((e._face||0)+1)/2*span),0,span);
  return `nmt_r${D.row}_${idx}`;
}
function drawMini(e){
  if(typeof XART==='undefined') return false;
  const k=miniArtKey(e); if(!k||!XART.rdy(k)) return false;
  const D=MINI_DEF[e._mini];
  const im=XART.get(k);
  const h=e.h*1.5*D.scale, w=h*(im.naturalWidth/im.naturalHeight);
  ctx.save(); ctx.translate(e.x,e.y);
  ctx.drawImage(im,-w/2,-h/2,w,h);
  /* HIT FLASH via xartTint, never ctx.filter. Canvas filters are an HTML/CSS effect: they render
     inconsistently across contexts, do not respect the pixel-art look, and were why several units
     never appeared to light up when shot. Tinting the sprite keeps its silhouette exactly. */
  if(e.flash>0 && typeof xartTint==='function'){
    const _tc=xartTint(k, e.flash>0.04?'#ffffff':'#ff8a4a', 0.85);
    if(_tc) ctx.drawImage(_tc,-w/2,-h/2,w,h);
  }
  ctx.restore();
  return true;
}
function miniTick(e, dt){
  const D=MINI_DEF[e._mini]; if(!D) return;
  // slow turn toward the player so the rotation frames get used
  if(player && !player.dead){
    const want=clamp((player.x-e.x)/120,-1,1);
    e._face=(e._face||0)+(want-(e._face||0))*Math.min(1,dt*2.2);
  }
  // ---- PATROL on the unit's own axis, and never leave its terrain ----
  if(e._pdir==null) e._pdir=(Math.random()<0.5?-1:1);
  const spd=(D.axis==='h'?26:16)*dt;
  if(D.axis==='h'){
    const nx=e.x+e._pdir*spd;
    if(miniTerrainOK(D.terr, nx, e.y, e.w) && nx>16 && nx<worldWidth()-16) e.x=nx;
    else e._pdir*=-1;                                  // hit the bank -> turn around
  } else {
    const ny=e.y+e._pdir*spd;
    if(miniTerrainOK(D.terr, e.x, ny, e.w) && ny>30 && ny<VH-30) e.y=ny;
    else e._pdir*=-1;                                  // hit the cliff -> turn around
  }
  // The master scrolls underneath, so a unit can be carried into blocked terrain. Search BOTH
  // axes for the nearest valid footing and slide it there — a boat tracks its channel, a tank
  // steps back off the rock.
  if(!miniTerrainOK(D.terr, e.x, e.y, e.w)){
    let moved=false;
    for(let r=5;r<=140 && !moved;r+=5){
      const cand=[[r,0],[-r,0],[0,r],[0,-r],[r*0.7,r*0.7],[-r*0.7,r*0.7],[r*0.7,-r*0.7],[-r*0.7,-r*0.7]];
      for(const [dx,dy] of cand){
        const tx=clamp(e.x+dx,16,worldWidth()-16), ty=clamp(e.y+dy,24,VH-24);
        if(miniTerrainOK(D.terr, tx, ty, e.w)){ e.x=tx; e.y=ty; moved=true; break; }
      }
    }
    if(!moved) e.dead=true;      // channel ran out entirely — retire it rather than beach it
  }
  // PELLET BALLS — a short spread burst, not a stream
  e._pel=(e._pel==null?rnd(0.6,1.6):e._pel)-dt;
  if(e._pel<=0 && !e.dead && e._dyingT==null){
    e._pel=D.fr*rnd(0.85,1.25)/Math.max(0.4,DIFF.eFire);
    const ang=Math.atan2((player?player.y:VH)-e.y,(player?player.x:e.x)-e.x);
    for(const off of [-0.16,0,0.16]) eShootT(e.x, e.y+e.h*0.3, ang+off, 2.1, 'pellet', null);
    e._muz=0.12;
  }
  if(e._muz>0) e._muz-=dt;
}
