    if(!unlocked){ key='nss_flag'+st+'_lock'; grayed=true; }
    else if(st===sselCursor && sselBoot===0){ key='nss_flag'+st+'_hi'+(((stateT*6)|0)%2); }
    else if(beaten){ key='nss_flag'+st+'_done'; tint=rankFlagColor(campaign.rank[st]); }
    else { key='nss_flag'+st+'_av'; tint=null; }   // PLAYABLE frontier: the flag stays its ORIGINAL green — no palette swap

    // unlock cinematic: the just-unlocked flag flashes white rapidly before settling to its true colors
    if(cine && cine.stage===st && cine.phase==='ding'){ if((cine.t*12|0)%2) tint='white'; }

