    if(sselBoot>0){ const age=sselBootT-(4.05+(st-1)*0.20); if(age>=0&&age<0.18) dropY=-(1-age/0.18)*14; }
    const fx=MX+p[0]*S-fw/2, fy=MY+p[1]*S-fh+dropY;
