/* ===== STAGE INTRO + STAGE FONT/* ===== STAGE INTRO + STAGE FONT (master-art) ===== */
/* STAGE ART EXISTS FOR STAGES 1-5 ONLY. Stages 6, 7 and 8 have no entry at all, so curArt()
   returned undefined and everything downstream that draws from the stage atlas — the INTRO card
   above all — had nothing to render. That is the broken level-6 intro. Falling back to stage 1's
   atlas means those stages get a card in the base style instead of no card. */
function curArt(){
  const A=ASSETS.stageArt;
  if(!A) return null;
  return A[String(run.stage)] || A['1'] || null;
}
function curFontArt(){
  /* THE BOF FONT FIRST (drop 0809g) — one typeface for the whole game. Stages 1-8 have their own
     tint of it; stage 9 falls back to stage 8's rather than dropping to a different face, because
     mixing typefaces mid-screen is the bug this replaces. */
  const bf=ASSETS.bofFont && (ASSETS.bofFont[String(run.stage)] || ASSETS.bofFont['8']);
  if(bf && bf.img && bf.img.complete && bf.img.naturalWidth) return bf;
  const nf=ASSETS.stageFont && ASSETS.stageFont[String(run.stage)];
  if(nf && nf.img && nf.img.complete && nf.img.naturalWidth) return nf;
  return curArt();
}
/* GLYPH FALLBACK. Stage 1's font carries 58 glyphs; every other stage font carries 46 — the
   punctuation set (" # $ % ( ) * ; = @ \ _) is absent. A stage font that lacks a character used to
   draw nothing at all for it. Any glyph the stage font does not have is now taken from stage 1's
   complete set, so text can never silently lose characters. */
function fontGlyph(art, ch){
  /* RECOVERED STAGE FONTS (drop 0724bq). Stages 6/7/8 (and the bonus stage 9) now have their
     ORIGINAL matching atlases, sliced to individual glyphs as sfont<N>_<char>. Prefer those over
     the atlas font, and keep the stage-1 fallback underneath for any character none of them has. */
  const st=(typeof run!=='undefined'&&run)?run.stage:1;
  if(typeof XART!=='undefined' && ch){
    const safe = /^[A-Za-z0-9]$/.test(ch) ? ch : ('p'+String(ch.charCodeAt(0)).padStart(2,'0'));
    const k='sfont'+st+'_'+safe;
    if(XART.rdy(k)) return {xart:k};
  }
  if(art && art.font && art.font[ch]) return {art:art, key:art.font[ch]};
  const base=ASSETS.stageFont && ASSETS.stageFont['1'];
  if(base && base.font && base.font[ch]) return {art:base, key:base.font[ch]};
  /* THE GAMEFONT WAS NEVER IN THE CHAIN (drop 0801gj). It carries the complete
     punctuation set as ncm_font_c<NNN> - three-digit ASCII - while the stage fonts
     use p<NN>, two digits. Measured on stage 6: only "(" and ")" of eleven
     punctuation marks resolved, so " # $ % * ; = @ _ rendered as nothing.
     ncm_font_c034 / c035 / c036 were registered the whole time; nothing looked
     for them. This is the last rung, so stage art still wins where it exists. */
  if(typeof XART!=='undefined' && ch){
    const g='ncm_font_'+(/^[A-Za-z0-9]$/.test(ch) ? ch : ('c'+String(ch.charCodeAt(0)).padStart(3,'0')));
    if(XART.rdy(g)) return {xart:g};
    if(/^[A-Z]$/.test(ch) && XART.rdy('ncm_font_'+ch.toLowerCase())) return {xart:'ncm_font_'+ch.toLowerCase()};
  }
  return null;
}
// UI font — the stage-1 stone font, used for ALL in-game/UI text everywhere
function uiFontArt(){
  /* THE UI FACE (drop 0809g). Mike: "these are your new stage font, pilot card, dialogue and
     stats fonts." Everything outside the stage banner — pilot cards, dialogue, the stats screen,
     menus — comes through here, so pointing it at the BOF font is what makes the game speak in
     ONE typeface instead of three.

     Stage 1's tint is the UI default because it is the most neutral of the eight; the coloured
     ones read as stage identity rather than chrome. */
  const bf=ASSETS.bofFont && ASSETS.bofFont['1'];
  if(bf && bf.img && bf.img.complete && bf.img.naturalWidth) return bf;
  const nf=ASSETS.stageFont && ASSETS.stageFont['1'];
  if(nf && nf.img && nf.img.complete && nf.img.naturalWidth) return nf;
  return (ASSETS.stageArt && ASSETS.stageArt['1']);
}
function artReady(a){ return a && a.img && a.img.complete && a.img.naturalWidth>0; }
const _ftc=document.createElement('canvas'), _ftx=_ftc.getContext('2d');
function drawFrameTinted(img,f,dx,dy,dw,dh,tintC,tintA,alpha){
  if(tintC){
    _ftc.width=f[2];_ftc.height=f[3];
    _ftx.globalCompositeOperation='source-over';_ftx.globalAlpha=1;_ftx.clearRect(0,0,f[2],f[3]);
    _ftx.drawImage(img,f[0],f[1],f[2],f[3],0,0,f[2],f[3]);
    _ftx.globalCompositeOperation='source-atop';_ftx.globalAlpha=(tintA==null?0.8:tintA);
    _ftx.fillStyle=tintC;_ftx.fillRect(0,0,f[2],f[3]);
    _ftx.globalAlpha=1;_ftx.globalCompositeOperation='source-over';
    ctx.save(); if(alpha!=null)ctx.globalAlpha=alpha;
    ctx.drawImage(_ftc,0,0,f[2],f[3],dx,dy,dw,dh); ctx.restore();
  } else {
    ctx.save(); if(alpha!=null)ctx.globalAlpha=alpha;
    ctx.drawImage(img,f[0],f[1],f[2],f[3],dx,dy,dw,dh); ctx.restore();
  }
}
// centered bitmap-font text at pixel height H; tintC null = original colors
/* THE GAME FONT AS TEXT (drop 0801bw). Mike: "use scaled down versions for each
   pilot's dialogue from this which I found in our game folder."

   assets/fonts/gamefont/ncm_font_* is a full 26-letter + 10-digit + punctuation
   bitmap face. I previously reported it as missing B G M N P V - that was wrong.
   Those six export as LOWERCASE filenames (ncm_font_b.png), almost certainly a
   case-collision at export time, and my audit was case-sensitive. They are now
   aliased so an uppercase lookup resolves all 26.

   gameText draws a string from those glyphs at a given cap height, left-aligned.
   gameTextWrap breaks on words to a pixel width and returns the line count, so
   the pilot bio can be typeset into the card's column instead of relying on the
   page font. */
function gameGlyph(ch){
  if(typeof XART==='undefined') return null;
  if(ch===' ') return null;
  const code=ch.charCodeAt(0);
  let k='ncm_font_'+ch.toUpperCase();
  if(!(XART._src && XART._src[k])) k='ncm_font_c'+String(code).padStart(3,'0');
  return (XART._src && XART._src[k] && XART.rdy(k)) ? XART.get(k) : null;
}
function gameTextW(text,H,sp){
  const s=(sp==null?H*0.12:sp); let w=0;
  for(const ch of String(text)){
    if(ch===' '){ w+=H*0.40+s; continue; }
    const im=gameGlyph(ch);
    w+=(im?H*(im.naturalWidth/im.naturalHeight):H*0.40)+s;
  }
  return Math.max(0,w-s);
}
function gameText(text,x,y,H,color,alpha,sp){
  if(typeof XART==='undefined') return 0;
  const s=(sp==null?H*0.12:sp); let cx2=x;
  ctx.save(); ctx.globalAlpha=(alpha==null?1:alpha);
  for(const ch of String(text)){
    if(ch===' '){ cx2+=H*0.40+s; continue; }
    const im=gameGlyph(ch);
    if(im){
      const w=H*(im.naturalWidth/im.naturalHeight);
      const tc=(color && typeof xartTint==='function') ? xartTint('ncm_font_'+ch.toUpperCase(),color,0.9) : null;
      ctx.drawImage(tc||im, Math.round(cx2), Math.round(y-H/2), Math.round(w), Math.round(H));
      cx2+=w+s;
    } else cx2+=H*0.40+s;
  }
  ctx.restore();
  return cx2-x;
}
function gameTextWrap(text,x,y,H,maxW,lineMul,color,alpha,budget){
  const words=String(text).split(' '); let line='', yy=y, n=0, used=0;
  const flush=()=>{ if(line){ gameText(line,x,yy,H,color,alpha); yy+=H*(lineMul||1.55); n++; line=''; } };
  for(const w of words){
    if(budget!=null && used>=budget) break;
    const t=line?(line+' '+w):w;
    if(gameTextW(t,H)>maxW && line){ flush(); line=w; } else line=t;
    used+=w.length+1;
  }
  flush();
  return n;
}
/* STAGE-FONT BODY TEXT (drop 0801ca). Mike: "I can barely see our dialogue text
   ... use our stage fonts for everything, never color overlay anything."

   Two separate reasons the bio was unreadable, and I caused both:

     1. It was drawn in the ncm_ GAMEFONT, a thin small face, at 2.1% of the card
        height. Fine for a campaign-map label, far too light for a paragraph.
     2. Every glyph went through xartTint with '#cfd6e6'. Tinting a already-shaded
        armored glyph flattens it to a wash — which is exactly the overlay rule
        this project already has for sprites, and I broke it on text.

   stageWrap measures words off the same frame rects stageText draws from, breaks
   to a pixel column, and draws each line through stageText with NO tint at all.
   The armored faces carry their own colour and shading; nothing is painted over
   them. */
function stageWidth(art,text,H,spacingMul){
  if(!art||!art.font) return 0;
  const sp=(spacingMul==null?0.10:spacingMul)*H; let w=0;
  for(const ch of String(text).toUpperCase()){
    if(ch===' '){ w+=H*0.42+sp; continue; }
    const nm=art.font[ch];
    if(!nm||!art.frames[nm]){ w+=H*0.42+sp; continue; }
    const f=art.frames[nm]; w+=f[2]*(H/f[3])+sp;
  }
  return Math.max(0,w-sp);
}
/* ============================================================
   FIT TEXT TO A COLUMN (drop 0809i)

   Mike, on the pilot card: "please do and show me the cards how they look loaded after."

   The card's type sizes were fixed fractions of card height, tuned against a NARROWER typeface.
   The BOF font is wider per character, so the same fraction overran the column — the bio clipped
   at "ELIT", "BOTH T", "SKIES" while the bottom third of the bay sat empty.

   Rather than hand-retune every size for this font and have it break on the next one, this
   measures the text and returns the largest size that fits. A font swap then costs nothing. */
function stageFitH(art, text, maxW, wantH, minH, spacingMul){
  if(!art || !art.font) return wantH;
  let h=wantH;
  const lo=(minH!=null)?minH:wantH*0.55;
  for(let i=0;i<24 && h>lo;i++){
    if(stageWidth(art, text, h, spacingMul||0.06) <= maxW) return h;
    h*=0.94;
  }
  return Math.max(lo,h);
}
/* the largest size at which EVERY line of a block fits — a block is only as readable as its
   longest line, so sizing per-line would make the paragraph ragged */
function stageFitBlock(art, lines, maxW, wantH, minH, spacingMul){
  let h=wantH;
  for(const t of lines) h=Math.min(h, stageFitH(art, t, maxW, wantH, minH, spacingMul));
  return h;
}
function stageWrap(art,text,x,y,H,maxW,lineMul,alpha,spacingMul){
  if(!art||!art.font) return 0;
  const words=String(text).split(' ');
  let line='', yy=y, n=0;
  const flush=()=>{
    if(!line) return;
    const w=stageWidth(art,line,H,spacingMul);
    // stageText centres on cx, so offset by half the line to left-align the block
    stageText(art,line,x+w/2,yy,H,null,null,alpha,spacingMul);
    yy+=H*(lineMul||1.5); n++; line='';
  };
  for(const wd of words){
    const t=line?(line+' '+wd):wd;
    if(stageWidth(art,t,H,spacingMul)>maxW && line){ flush(); line=wd; }
    else line=t;
  }
  flush();
  return n;
}
function stageText(art,text,cx,cy,H,tintC,tintA,alpha,spacingMul){
  if(!art||!art.font) return;
  const sp=(spacingMul==null?0.10:spacingMul)*H; const items=[]; let total=0;
  for(const ch of String(text).toUpperCase()){
    if(ch===' '){ items.push(null); total+=H*0.42+sp; continue; }
    const nm=art.font[ch]; if(!nm||!art.frames[nm]){ items.push(null); total+=H*0.42+sp; continue; }
    const f=art.frames[nm], w=f[2]*(H/f[3]); items.push([f,w]); total+=w+sp;
  }
  total-=sp; let x=cx-total/2;
  for(const it of items){
    if(!it){ x+=H*0.42+sp; continue; }
    const f=it[0], w=it[1];
    drawFrameTinted(art.img,f,Math.round(x),Math.round(cy-H/2),Math.round(w),Math.round(H),tintC,tintA,alpha);
    x+=w+sp;
  }
}
let introSeq={crash:false,slice:false,mus:false,debris:null,lastnum:99,go:false};
// ---- OFFICIAL GAME FONT: Stage-1 bitmap font as the default for all messages/dialogue.
// Stage-1 font lacks 'S' (and a few glyphs) -> borrow those from the Stage-2 font atlas.
function defFontArt(){ return uiFontArt() || curFontArt() || (ASSETS.stageArt && (curArt() || ASSETS.stageArt['1'])); }
function defFontAlt(){ return (ASSETS.stageFont && ASSETS.stageFont['1']) || (ASSETS.stageArt && ASSETS.stageArt['1']); }
function msgText(text,cx,cy,H,tintC,tintA,alpha,spacingMul){
  const a1=defFontArt(), a2=defFontAlt();
  if(!a1||!a1.font||!a1.img||!a1.img.complete){
    ctx.save(); ctx.font='900 '+Math.round(H*0.86)+'px "Arial Black",Impact,sans-serif';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.globalAlpha=(alpha==null?1:alpha); ctx.fillStyle=tintC||'#ffce4a';
    ctx.fillText(String(text).toUpperCase(),cx,cy); ctx.restore(); return;
  }
  const sp=(spacingMul==null?0.10:spacingMul)*H; const items=[]; let total=0;
  for(const ch of String(text).toUpperCase()){
    if(ch===' '){ items.push(null); total+=H*0.42+sp; continue; }
    let art=a1, nm=a1.font[ch];
    if((!nm||!a1.frames[nm]) && a2 && a2.font && a2.font[ch] && a2.frames[a2.font[ch]]){ art=a2; nm=a2.font[ch]; }
    if(!nm||!art.frames[nm]){ items.push(null); total+=H*0.42+sp; continue; }
    const f=art.frames[nm], w=f[2]*(H/f[3]); items.push([art,f,w]); total+=w+sp;
  }
  total-=sp; let x=cx-total/2;
  for(const it of items){
    if(!it){ x+=H*0.42+sp; continue; }
    const art=it[0], f=it[1], w=it[2];
    drawFrameTinted(art.img,f,Math.round(x),Math.round(cy-H/2),Math.round(w),Math.round(H),tintC,tintA,alpha);
    x+=w+sp;
  }
}
function resetIntro(){ introSeq={crash:false,slice:false,mus:false,debris:[],lastnum:99,go:false}; }
function drawCardFX(art,lx,ty,w,h,t){
  const fx=art.fx; const A=art.anchors||{};
  const tc=A.torch||{cx:0.058,by:0.84,scl:0.075};
  const sk=A.skull||{cx:0.50,cy:0.85,w:0.17};
  const sm=A.smoke||{by:0.60,scl:0.12};
  const em=A.embers||{by:0.66,scl:0.13};
  const ov=A.overlay||{y:0.12};
  const cyc=(arr,fps)=>arr&&arr.length?arr[Math.floor(t*fps)%arr.length]:null;
  const blitFrac=(name,cxf,byf,scl,blend,alpha)=>{
    if(!name) return; const f=art.frames[name]; if(!f) return;
    const fw=w*scl, fh=fw*(f[3]/f[2]); const cx=lx+w*cxf, by=ty+h*byf;
    ctx.save(); if(blend)ctx.globalCompositeOperation=blend; if(alpha!=null)ctx.globalAlpha=alpha;
    ctx.drawImage(art.img,f[0],f[1],f[2],f[3],Math.round(cx-fw/2),Math.round(by-fh),fw,fh); ctx.restore();
  };
  const tox=tc.offx||0;
  blitFrac(cyc(fx.smoke,10),tc.cx+tox,sm.by,sm.scl,null,0.6);
  blitFrac(cyc(fx.smoke,10),1-tc.cx+tox,sm.by,sm.scl,null,0.6);
  blitFrac(cyc(fx.embers,14),tc.cx+tox,em.by,em.scl,'lighter',0.85);
  blitFrac(cyc(fx.embers,14),1-tc.cx+tox,em.by,em.scl,'lighter',0.85);
  blitFrac(cyc(fx.left_torch,12),tc.cx+tox,tc.by,tc.scl,null,1);
  blitFrac(cyc(fx.right_torch,12),1-tc.cx+tox,tc.by,tc.scl,null,1);
  const skn=cyc(fx.skull_eyes,9), sf=skn&&art.frames[skn];
  if(sf){ const sw=w*sk.w, sh=sw*(sf[3]/sf[2]), scx=lx+w*sk.cx, scy=ty+h*sk.cy;
    ctx.save(); ctx.globalAlpha=1;
    ctx.drawImage(art.img,sf[0],sf[1],sf[2],sf[3],Math.round(scx-sw/2),Math.round(scy-sh/2),sw,sh); ctx.restore(); }
  const ffn=cyc(fx.fireflies,8), ff=ffn&&art.frames[ffn];
  const ovA=(ov.alpha!=null)?ov.alpha:0.85;
  if(ff && ovA>0){ const fw=w, fh=fw*(ff[3]/ff[2]); ctx.save(); ctx.globalAlpha=ovA;
    ctx.drawImage(art.img,ff[0],ff[1],ff[2],ff[3],Math.round(lx),Math.round(ty+h*ov.y),fw,fh); ctx.restore(); }
}
function spawnCardDebris(cx,cy,w,h){
  introSeq.debris=[];
  for(let i=0;i<48;i++){ const a=rnd(0,TAU), s=rnd(1,5.2);
    introSeq.debris.push({x:cx+rnd(-w*0.45,w*0.45),y:cy+rnd(-h*0.4,h*0.4),vx:Math.cos(a)*s,vy:Math.sin(a)*s-1.2,
      life:rnd(0.4,1.0),t:0,r:rnd(1.5,4),c:chance(0.45)?'#7a8a5a':(chance(0.5)?'#cfd6c0':'#3a5a28')}); }
}
function updateDrawDebris(dt){
  if(!introSeq.debris) return;
  for(const p of introSeq.debris){ p.t+=dt; if(p.t>p.life)continue; p.x+=p.vx; p.y+=p.vy; p.vy+=0.25; p.vx*=0.98;
    ctx.globalAlpha=clamp(1-p.t/p.life,0,1); ctx.fillStyle=p.c; ctx.fillRect(p.x|0,p.y|0,p.r,p.r); }
  ctx.globalAlpha=1;
}
function drawBurn(art,cf,ccx,ccy,w,h,t,dt){
  const bp=clamp((t-3.0)/(3.95-3.0),0,1);
  const lx=ccx-w/2, ty=ccy-h/2; const burnY=Math.round(ty+bp*h);
  // unburned card + its lit fx, clipped to below the descending burn frontier
  ctx.save(); ctx.beginPath(); ctx.rect(0,burnY,VW,VH-burnY); ctx.clip();
  ctx.drawImage(art.img,cf[0],cf[1],cf[2],cf[3],Math.round(lx),Math.round(ty),w,h);
  drawCardFX(art,lx,ty,w,h,t);
  ctx.restore();
  if(!introSeq.ash) introSeq.ash=[];
  if(bp<1){
    // glowing ember frontier
    const g=ctx.createLinearGradient(0,burnY-16,0,burnY+5);
    g.addColorStop(0,'rgba(0,0,0,0)'); g.addColorStop(0.42,'rgba(170,40,8,0.45)');
    g.addColorStop(0.74,'rgba(255,150,40,0.85)'); g.addColorStop(0.9,'rgba(255,235,140,0.95)'); g.addColorStop(1,'rgba(50,16,8,0.65)');
    ctx.save(); ctx.fillStyle=g; ctx.fillRect(lx,burnY-16,w,21);
    for(let i=0;i<14;i++){ const px=lx+rnd(0,w); ctx.fillStyle='rgba(255,'+rint(120,235)+',55,'+rnd(0.3,0.85)+')'; ctx.fillRect(px,burnY-rnd(1,12),rnd(2,5),rnd(2,9)); }
    ctx.restore();
    // occasional crackle
    if(chance(0.12)) Audio.SFX.crackle&&Audio.SFX.crackle();
    // spawn ash (falls) + embers (rise)
    for(let i=0;i<7;i++){ const px=lx+rnd(0,w);
      introSeq.ash.push({x:px,y:burnY,vx:rnd(-0.5,0.5),vy:rnd(0.3,1.7),life:rnd(0.6,1.5),t:0,r:rnd(1,3),g:0.05,c:chance(0.5)?'#2a2622':'#48433b'});
      if(chance(0.6)) introSeq.ash.push({x:px,y:burnY,vx:rnd(-0.7,0.7),vy:-rnd(0.7,2.4),life:rnd(0.4,0.95),t:0,r:rnd(1,2.6),g:0.03,em:1,c:chance(0.5)?'#ff8a2a':'#ffd25a'});
    }
  }
  for(const p of introSeq.ash){ p.t+=dt; if(p.t>p.life) continue; p.x+=p.vx; p.y+=p.vy; p.vy+=p.g; if(p.em)p.vx*=0.99;
    ctx.globalAlpha=clamp(1-p.t/p.life,0,1)*(p.em?0.9:0.8); ctx.fillStyle=p.c; ctx.fillRect(p.x|0,p.y|0,p.r,p.r); }
  ctx.globalAlpha=1;
}
function drawShatter(art,cf,ccx,ccy,w,h,t,dt){
  const bp=clamp((t-3.0)/(3.95-3.0),0,1);
  const lx=ccx-w/2, ty=ccy-h/2; const FREEZE=0.42;
  if(!introSeq.ash) introSeq.ash=[];
  if(bp<FREEZE){
    const fp=bp/FREEZE;
    ctx.drawImage(art.img,cf[0],cf[1],cf[2],cf[3],Math.round(lx),Math.round(ty),w,h);
    drawCardFX(art,lx,ty,w,h,t);
    // icy wash creeping over the card
    ctx.save(); ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=fp*0.42;
    ctx.fillStyle='#6ea6e6'; ctx.fillRect(lx,ty,w,h); ctx.restore();
    // frost crystals accumulating (deterministic per index, count grows with fp)
    ctx.save(); ctx.globalAlpha=0.5+0.5*fp;
    const nf=Math.floor(fp*70);
    for(let i=0;i<nf;i++){ const sx=lx+((i*0.61803)%1)*w, sy=ty+((i*0.7549+i*i*0.013)%1)*h;
      const r=1+((i*13)%3); ctx.fillStyle = (i%3? 'rgba(210,235,255,0.9)':'rgba(255,255,255,0.95)');
      ctx.fillRect(sx|0,sy|0,r,r);
      if(i%4===0){ ctx.strokeStyle='rgba(200,230,255,0.5)'; ctx.lineWidth=1; ctx.beginPath(); ctx.moveTo(sx,sy); ctx.lineTo(sx+(i%5-2)*3, sy+((i%3)-1)*3); ctx.stroke(); } }
    ctx.restore();
  } else {
    const sp=clamp((bp-FREEZE)/(1-FREEZE),0,1);
    if(!introSeq.cracked){ introSeq.cracked=true; Audio.SFX.shatter(); shake=Math.max(shake,14);
      for(let i=0;i<46;i++){ const a=rnd(0,TAU), s=rnd(2.5,10);
        introSeq.ash.push({x:ccx,y:ccy,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rnd(0.45,1.1),t:0,r:rnd(1,3.5),g:0.06,c:chance(0.5)?'#cfe8ff':'#ffffff'}); } }
    // card bursts into radial shards flying outward
    const N=11;
    for(let i=0;i<N;i++){
      const a0=(i/N)*TAU, a1=((i+1)/N)*TAU, bis=(a0+a1)/2;
      const dist=sp*sp*300, dx=Math.cos(bis)*dist, dy=Math.sin(bis)*dist, R=Math.max(w,h);
      ctx.save(); ctx.globalAlpha=clamp(1-sp*1.05,0,1);
      ctx.beginPath(); ctx.moveTo(ccx,ccy); ctx.lineTo(ccx+Math.cos(a0)*R,ccy+Math.sin(a0)*R); ctx.lineTo(ccx+Math.cos(a1)*R,ccy+Math.sin(a1)*R); ctx.closePath(); ctx.clip();
      ctx.translate(dx,dy); ctx.translate(ccx,ccy); ctx.rotate(sp*0.6*((i%2)?1:-1)); ctx.translate(-ccx,-ccy);
      ctx.drawImage(art.img,cf[0],cf[1],cf[2],cf[3],Math.round(lx),Math.round(ty),w,h);
      ctx.globalCompositeOperation='lighter'; ctx.globalAlpha=clamp(1-sp,0,1)*0.3; ctx.fillStyle='#8ec0f0'; ctx.fillRect(lx,ty,w,h);
      ctx.restore();
    }
    if(sp<0.12){ ctx.save(); ctx.globalAlpha=(0.12-sp)/0.12*0.7; ctx.fillStyle='#e6f4ff'; ctx.fillRect(0,0,VW,VH); ctx.restore(); }
  }
  for(const p of introSeq.ash){ p.t+=dt; if(p.t>p.life) continue; p.x+=p.vx; p.y+=p.vy; p.vy+=p.g; p.vx*=0.99;
    ctx.globalAlpha=clamp(1-p.t/p.life,0,1); ctx.fillStyle=p.c; ctx.fillRect(p.x|0,p.y|0,p.r,p.r); }
  ctx.globalAlpha=1;
}
function proceedIntro(){ resetIntro(); drawIntro._snd=false; setState(GS.LAUNCH); }
/* STAGE INTRO — master-art animated card with crash-in, fx, slice, countdown */
function drawIntro(dt){
  const art=curArt();
  // NEW stage cards (stagecards_0716 pack): 800x480 alpha cards with the title embedded, all 8 stages.
  // Preferred over the old atlas card; falls back to atlas art, then the legacy banner.
  let _cimg=null, cf=null;
  const _sk='scard_'+run.stage;
  if(typeof XART!=='undefined' && XART.rdy(_sk)){ _cimg=XART.get(_sk); cf=[0,0,_cimg.naturalWidth,_cimg.naturalHeight]; }
  else if(artReady(art)){ _cimg=art.img; cf=art.frames['card']; }
  else return drawIntroLegacy(dt);
  const t=stateT;
  if(t<0.02) resetIntro();
  /* the stage's authored INTRO card, typed under the art once the card has landed */
  if(typeof arcStageCard==='function' && t>1.1){
    const ic=arcStageCard(run.stage,'intro');
    if(ic) arcDraw(ic, VW/2, VH*0.72, 12, clamp((t-1.1)/1.6,0,1), '#ffe082');
  }
  // SIMPLE card drop: falls in from the top -> THUD + screen shake -> drops down and off-screen.
  const DROPIN=0.62, HOLD=2.6, DROPOUT=3.5, CD=3.6;
  ctx.fillStyle='#000'; ctx.fillRect(0,0,VW,VH);
  if(t>0.05 && !introSeq.mus){ introSeq.mus=true; Audio.startMusic((curStage&&curStage.music)||'stage'); }
  const fullW=Math.min(VW-20, cf[2]); const fullH=fullW*(cf[3]/cf[2]);
  const ccx=VW/2, restY=VH*0.44;
  let cy=restY, cardA=1;
  if(t<DROPIN){
    // back-ease drop from above to the rest position
    const pp=clamp(t/DROPIN,0,1), c1=1.70158, c3=c1+1, e=1+c3*Math.pow(pp-1,3)+c1*Math.pow(pp-1,2);
    cy=lerp(-fullH*0.7, restY, e);
  } else if(t>=HOLD){
    // accelerate downward off the bottom of the screen
    const sp=clamp((t-HOLD)/(DROPOUT-HOLD),0,1), e=sp*sp;   // ease-in (gravity)
    cy=lerp(restY, VH+fullH*0.7, e);
    cardA=1-clamp((sp-0.7)/0.3,0,1);
  }
  // THUD + shake exactly when the card lands (end of drop-in)
  if(t>=DROPIN*0.92 && !introSeq.crash){ introSeq.crash=true; shake=Math.max(shake,16); if(Audio.SFX.crash)Audio.SFX.crash(); else if(Audio.SFX.expBig)Audio.SFX.expBig(); }
  const w=fullW, h=fullH;
  ctx.save();
  if(shake>0){ ctx.translate(rnd(-shake,shake),rnd(-shake,shake)); shake=Math.max(0,shake-dt*40); }
  ctx.globalAlpha=cardA;
  ctx.drawImage(_cimg,cf[0],cf[1],cf[2],cf[3],Math.round(ccx-w/2),Math.round(cy-h/2),w,h);
  // (torch/skull card FX removed per Mike)
  ctx.restore();
  if(t>=CD){ proceedIntro(); }
  if(t>0.7 && t<CD && (Input.tap('enter')||keybind.fire.some(k=>Input.tap(k)))){ stateT=CD-0.001; }
}

/* legacy procedural intro (stages without master art) */
function drawIntroLegacy(dt){
  drawBG(dt);
  if(stateT>0.1 && !drawIntro._mus){ drawIntro._mus=true; Audio.startMusic((curStage&&curStage.music)||'stage'); }
  const card = ASSETS.cards && ASSETS.cards[run.stage-1];
  const proceed=()=>{ drawIntro._snd=false; drawIntro._mus=false; setState(GS.LAUNCH); };
  if(ASSETS.rdy(card)){
    ctx.fillStyle='rgba(0,0,0,0.45)'; ctx.fillRect(0,0,VW,VH);
    const bw=Math.min(VW-24, card.naturalWidth), bh=card.naturalHeight*(bw/card.naturalWidth);
    // back-ease fly-in from top
    const pp=clamp(stateT/0.55,0,1), c1=1.70158, c3=c1+1, e=1+c3*Math.pow(pp-1,3)+c1*Math.pow(pp-1,2);
    const yy=lerp(-bh, VH*0.42, e);
    const fade=stateT>2.4?clamp(1-(stateT-2.4)/0.6,0,1):1;
    ctx.save(); ctx.globalAlpha=fade; ctx.shadowColor='#000'; ctx.shadowBlur=14;
    ctx.drawImage(card, Math.round(VW/2-bw/2), Math.round(yy-bh/2), bw, bh); ctx.restore();
    // press-start hint
    if(stateT>0.7 && fade>0.5 && Math.floor(stateT*2)%2){ ctx.fillStyle='#dfe7f2'; ctx.font='bold 10px "BOFmil", monospace'; ctx.textAlign='center'; ctx.fillText('PRESS  FIRE',VW/2,VH*0.42+bh/2+22); }
    if(stateT>0.3 && !drawIntro._snd){ drawIntro._snd=true; Audio.SFX.select(); }
    if(stateT>3.0){ proceed(); }
    else if(stateT>0.6 && (Input.tap('enter')||keybind.fire.some(k=>Input.tap(k)))){ proceed(); }
    return;
  }
  // ---- fallback: legacy procedural banner ----
  const t=stateT;
  ctx.fillStyle='rgba(0,0,0,0.55)'; ctx.fillRect(0,0,VW,VH);
  const slide = clamp(t/0.5,0,1);
  const bx=VW/2, by=VH/2;
  ctx.save(); ctx.translate(lerp(-VW,bx,easeOut(slide)),by);
  metalBanner();
  ctx.fillStyle='#cfd6e0'; ctx.font='bold 12px "BOFmil", monospace'; ctx.textAlign='center';
  ctx.fillText(curStage.name, 0, -18);
  ctx.font='bold 22px "Arial Black",Impact,sans-serif';
  outlineText(curStage.sub,0,12,'#ff9a2e','#3a1500',3);
  ctx.fillStyle='#ffd36b'; ctx.fillText(curStage.sub,0,11);
  ctx.restore();
  if(t>0.6 && !drawIntro._snd){ drawIntro._snd=true; Audio.SFX.select(); }
  if(t>2.6){ proceed(); }
  if(t>1.0 && (Input.tap('enter')||keybind.fire.some(k=>Input.tap(k)))){ proceed(); }
}
/* ===== SIGNATURE LAUNCH CINEMATIC ===== */
const LAUNCH_TERR=['terr_grass','terr_desert','terr_ice','terr_road','terr_war'];
function _ease(x){ return x<0.5?2*x*x:1-Math.pow(-2*x+2,2)/2; }
let _slines=null;
function _speedLines(intensity){
  if(!_slines){ _slines=[]; for(let i=0;i<46;i++) _slines.push({x:rnd(0,VW),y:rnd(0,VH),len:rnd(20,90),sp:rnd(9,22)}); }
  ctx.save(); ctx.strokeStyle='rgba(255,255,255,'+(0.22*intensity)+')'; ctx.lineWidth=1.5;
  for(const l of _slines){ l.y+=l.sp; if(l.y>VH+l.len){ l.y=-l.len; l.x=rnd(0,VW); }
    ctx.beginPath(); ctx.moveTo(l.x,l.y); ctx.lineTo(l.x,l.y+l.len); ctx.stroke(); } ctx.restore();
}
function _scrollVAbs(img,dist){
  if(!img||!img.complete||!img.naturalWidth){ ctx.fillStyle='#0c0e12'; ctx.fillRect(0,0,VW,VH); return; }
  const sc=Math.max(VW/img.naturalWidth, VH/img.naturalHeight), dw=img.naturalWidth*sc, dh=img.naturalHeight*sc;
  let off=dist%dh; if(off<0)off+=dh;
  for(let yy=off-dh; yy<VH; yy+=dh){ ctx.drawImage(img,(VW-dw)/2,yy,dw,dh); }   /* NO flip */
}
/* draw the selected pilot's ship (idle '', bank '_l'/'_r'). '_t' is REFUSED — see drawShipSprite. */
function _shipK(suf){ const p=(run&&run.pilot)||'axel'; const k='ship_'+p+(suf||''); return (typeof XART!=='undefined'&&XART.rdy(k))?k:null; }
/* ============================================================
   ONE THRUSTER SYSTEM, EVERYWHERE (drop 0808g)

   Mike: "in cinematics, gameplay, stage intros, we always use these with the thrusters. no more
   static graphics with the thrusters built in."

   ship_<pilot>_t is the BAKED-IN variant, and it is measurably a different aircraft: it runs
   20-161px taller than the plain hull because the flame is part of the sprite (axel +161, decker
   +57, maverick +54, lizzie +44, yuri +20). Drawing it to a target HEIGHT therefore shrinks the
   actual airframe by however much flame is attached — which is why the ship looked a different
   size in the cinematic than in play, and why no mount table could ever line up against it.

   `_t` is refused here. Every caller gets the PLAIN hull at the requested height, with the live
   thruster drawn under it from the same THRUSTER_MOUNTS table gameplay uses. One system, one set
   of mounts, one place to fix it. ============================================================ */
function drawShipThruster(x, y, h, pilot, alpha){
  if(typeof XART==='undefined' || typeof THRUSTER_MOUNTS==='undefined') return;
  const p=pilot||(run&&run.pilot)||'cole';
  const cfg=THRUSTER_MOUNTS[p]; if(!cfg) return;
  const key='nthp_'+p+'_'+(((performance.now()/70)|0)%4);
  if(!XART.rdy(key)) return;
  const im=XART.get(key);
  const k0=_shipK(''); if(!k0) return;
  const hull=XART.get(k0);
  /* ⚠ MATCH THE PLAY PATH EXACTLY (drop 0809b). Mike: "whats up with the different thrusters as
     shown in cinematic and in-game?"

     In play the plume is sized against the hull's CANVAS width, which is derived by dividing the
     target content height by a per-pilot content factor (~0.80) — the sprite has transparent
     margin, so the canvas is about 25% bigger than the aircraft you see. This function sized
     against the drawn height directly, with no such division, so its hull reference came out
     ~25% small and the plume ~25% oversized. That is the whole discrepancy: same table, same
     scale value, different denominator.

     The content factors are duplicated from _drawPlayerCore rather than shared, which is a wart —
     but a wrong number here is a visible bug and a shared constant is a refactor. Noted for the
     next structural pass. */
  const _CFC={axel:0.8081, cole:0.8081, decker:0.7935, falva:0.7929, freezer:0.8081,
              juggernaut:0.7964, lizzie:0.8429, maverick:0.8022, yuri:0.7454};
  const _cfc=(_CFC[p]!=null)?_CFC[p]:0.80;
  const canvasH=h/_cfc;                                       // the canvas that yields this content height
  const w=canvasH*(hull.naturalWidth/hull.naturalHeight);     // the hull's CANVAS width, as in play
  const pw=Math.max(4, (cfg.scale||0.26)*w);
  const kk=pw/im.naturalWidth;
  const tw=im.naturalWidth*kk, th=im.naturalHeight*kk;
  const dy=(cfg.dy||0)*canvasH;
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  ctx.globalAlpha=(alpha==null?0.95:alpha);
  for(const mx of (cfg.mounts||[0])){
    const px=x+mx*w;
    /* anchored at the hull's own tail, as in play — h/2 is the DRAWN half-height, not the canvas */
    if(cfg.flip){ ctx.save(); ctx.translate(px, y+h/2+dy); ctx.scale(1,-1);
                  ctx.drawImage(im, -tw/2, 0, tw, th); ctx.restore(); }
    else ctx.drawImage(im, px-tw/2, y+h/2+dy, tw, th);
  }
  ctx.restore();
}
function drawShipSprite(x,y,h,suf){
  /* the baked-in variant is never used, whatever a caller asks for */
  const _s=(suf==='_t')?'':suf;
  let k=_shipK(_s); if(!k) k=_shipK('');
  if(k){
    const im=XART.get(k); const w=h*(im.naturalWidth/im.naturalHeight);
    drawShipThruster(x,y,h,(run&&run.pilot)||'cole', 0.95);   // behind the hull
    ctx.drawImage(im,x-w/2,y-h/2,w,h); return; }
  if(ASSETS.has&&ASSETS.has('player')){ const fr=ASSETS.dims('player'), sc=h/fr.h;
    // legacy player_thrust blit removed (drop 0724cj) — a second engine under our own
    ASSETS.blit('player',x,y,fr.w*sc,h); return; }
  ctx.save(); ctx.translate(x,y); ctx.scale(h/40,h/40); drawStaticPlayer(); ctx.restore();
}
function _groundScroll(dist){
  ctx.fillStyle='#000'; ctx.fillRect(0,0,VW,VH);
  const pad=XART.get('landingpad'), run=XART.get('runway');
  let padH=0; const padW=VW;
  if(pad&&pad.complete&&pad.naturalWidth){ padH=padW*(pad.naturalHeight/pad.naturalWidth); }
  const padTop=(VH+dist)-padH;                 /* pad bottom starts at VH, slides down as dist grows */
  if(run&&run.complete&&run.naturalWidth){     /* runway attached above the pad, seamless tiling */
    const rw=VW, rh=rw*(run.naturalHeight/run.naturalWidth); let y=padTop;
    while(y>-rh){ y-=rh; ctx.drawImage(run,0,y,rw,rh); }
  }
  if(pad&&pad.complete&&pad.naturalWidth) ctx.drawImage(pad,(VW-padW)/2,padTop,padW,padH);
}
function _pilotStill(P){
  if(typeof drawPilotBG==='function') drawPilotBG(P.tint); else { ctx.fillStyle='#101018'; ctx.fillRect(0,0,VW,VH); }
  const k='card_'+P.key;
  if(XART.rdy(k)){ const im=XART.get(k); let w=Math.min(VW-30,452), h=w*(im.naturalHeight/im.naturalWidth); const mh=VH*0.62; if(h>mh){h=mh;w=h*(im.naturalWidth/im.naturalHeight);} ctx.drawImage(im,VW/2-w/2,VH*0.455-h/2,w,h); }
}
/* ===== continuous filmstrip transition (NO fades / NO cuts) ===== */
const ANCHORY=0.60;                         /* player "front" as a screen fraction */
const SEG_B1=2000, SEG_B2=SEG_B1+2200, SEG_B3=SEG_B2+8800;   /* runway | terrain | liquid | level(entrance) */
function _liquidFrame(){
  /* Upgraded beds first (drop 0724f: seam-healed, native 1:1). These are real Image objects, so
     _region draws them directly; the legacy ASSETS path stays as the fallback for any stage
     whose bed was never upgraded. */
  if(typeof seqBedFrames==='function'){
    const fr=seqBedFrames(run.stage);
    if(fr && fr.length) return fr[Math.floor(performance.now()/150)%fr.length];
  }
  const s=run.stage; let frames=ASSETS.water; if(s===2)frames=ASSETS.lava;
  const f2=(frames&&frames.length)?frames[Math.floor(performance.now()/70)%frames.length]:null;
  return (f2&&ASSETS.rdy&&ASSETS.rdy(f2))?f2:null; }
/* tile an image across world-band [wStart,wEnd]; the world scrolls DOWN as dist grows (no fades) */
function _region(img,wStart,wEnd,dist,tint,fallback){
  const anchorY=VH*ANCHORY;
  const bandTop=anchorY-(wEnd-dist), bandBot=anchorY-(wStart-dist);
  const cTop=Math.max(0,bandTop), cBot=Math.min(VH,bandBot);
  if(cBot<=cTop) return;
  ctx.save(); ctx.beginPath(); ctx.rect(0,cTop,VW,cBot-cTop); ctx.clip();
  if(img&&img.complete&&img.naturalWidth){
    // NATIVE-SIZE LIQUIDS. This stretched every texture to the full VW, so the 128px liquid tiles
    // came out ~3.75x upscaled and mushy during the runway/launch scenes. A small square tile is
    // meant to TILE at 1:1 (that is the whole point of the 0724f tiling fix), so anything that is
    // roughly square and small is now drawn at its own size and repeated across, exactly like the
    // in-level tiler. Wide plates (runways, connectors, masters) still fill the width as before.
    const _sq = img.naturalWidth<=256 && Math.abs(img.naturalWidth-img.naturalHeight)<=img.naturalWidth*0.4;
    const dw = _sq ? img.naturalWidth : VW;
    const dh = _sq ? img.naturalHeight : dw*(img.naturalHeight/img.naturalWidth);
    for(let y=wStart; y<wEnd+dh; y+=dh){
      const st=anchorY-((y+dh)-dist);
      if(st>VH||st+dh<0) continue;
      if(dw<VW){ for(let xx=0; xx<VW; xx+=dw) ctx.drawImage(img, xx, st, dw, dh); continue; }
      ctx.drawImage(img,0,0,img.naturalWidth,img.naturalHeight,0,Math.round(st),dw,Math.ceil(dh));
    }
  } else if(fallback){ ctx.fillStyle=fallback; ctx.fillRect(0,cTop,VW,cBot-cTop); }
  if(tint){ ctx.fillStyle=tint; ctx.fillRect(0,cTop,VW,cBot-cTop);
    ctx.globalAlpha=0.45; ctx.fillStyle='#eaf9ff';
    for(let i=0;i<7;i++){ const y=cTop+((dist*0.5+i*96)%(cBot-cTop)); ctx.fillRect(0,Math.round(y),VW,2); } ctx.globalAlpha=1; }
  ctx.restore();
}
/* the stage itself scrolls in from the top (the "entrance"): drawBG clipped above the SEG_B3 seam */
function _drawLevelRegion(dist,dt){
  const seam=VH*ANCHORY-(SEG_B3-dist);
  if(seam<=0) return;
  ctx.save(); ctx.beginPath(); ctx.rect(0,0,VW,Math.min(VH,seam)); ctx.clip();
  drawBG(dt);
  ctx.restore();
}
function drawLaunch(dt){
  if(drawLaunch._phase===undefined || stateT < (drawLaunch._lastT||0)-0.001){ drawLaunch._dist=0; drawLaunch._spd=110; drawLaunch._phase='run'; drawLaunch._pt=0;
    drawLaunch._eng=false; drawLaunch._thr=false; drawLaunch._brk=false; drawLaunch._go=false; drawLaunch._num=99; drawLaunch._mus=false; }
  drawLaunch._lastT=stateT;
  const t=stateT;
  if(!drawLaunch._mus){ drawLaunch._mus=true; Audio.startMusic((curStage&&curStage.music)||'stage'); }
  const ph=drawLaunch._phase;
  /* ---- speed / phase machine: run is distance-driven so the level always shows before braking ---- */
  const _space=(run.stage===5);
  const _spdCap=_space?3200:1750;   // space launch is faster than we've ever gone
  if(ph==='run'){
    drawLaunch._spd=Math.min(_spdCap, drawLaunch._spd+(_space?2600:1500)*dt);
    drawLaunch._dist+=drawLaunch._spd*dt;
    if(drawLaunch._dist>=SEG_B3+240){ drawLaunch._phase='brake'; drawLaunch._pt=0; if(Audio.SFX.brake)Audio.SFX.brake(); }   /* sped a little past into the level */
    /* STAGE 6 is the exception Mike called out: runway -> SKY. It keeps climbing instead of
       settling onto ground, and the cloud deck thickens as it goes. */
    if(typeof seqCfg==='function' && seqCfg(run.stage).sky){
      drawLaunch._sky=clamp((drawLaunch._dist-SEG_B1)/Math.max(1,(SEG_B3-SEG_B1)),0,1);
      drawLaunch._spd=Math.min(_spdCap*1.35, drawLaunch._spd+900*dt);
    }
  } else if(ph==='brake'){
    drawLaunch._pt+=dt; const p=clamp(drawLaunch._pt/2.0,0,1); drawLaunch._spd=lerp(1750,0,_ease(p));
    drawLaunch._dist+=drawLaunch._spd*dt;                          /* level keeps scrolling in smoothly while braking */
    if(drawLaunch._pt>=2.0){ drawLaunch._phase='settle'; drawLaunch._pt=0; }
  } else if(ph==='settle'){
    /* WAS 'reverse': it shoved dist backwards by up to 300px, which read as the player being
       yanked back just before GO. Mike flagged it. Now the world simply comes to REST — no
       negative travel, no drift — and the ship holds the exact spot it will start play from. */
    drawLaunch._pt+=dt; drawLaunch._spd=0;
    if(drawLaunch._pt>=0.45){ drawLaunch._phase='cd'; drawLaunch._pt=0; }
  } else { drawLaunch._pt+=dt; drawLaunch._spd=0; }
  const dist=drawLaunch._dist, nrm=clamp(drawLaunch._spd/1750,0,1);
  const art=(typeof curArt==='function')&&curArt();
  const X=(typeof XART!=='undefined')?XART:null;
  /* ---- one continuous scroll (far->near): level entrance, liquid, terrain, runway, pad ---- */
  ctx.fillStyle='#05070a'; ctx.fillRect(0,0,VW,VH);
  const rum=nrm*4; ctx.save(); if(rum>0.2) ctx.translate(rnd(-rum,rum),rnd(-rum,rum));
  _drawLevelRegion(dist,dt);
  if(typeof seqCfg==='function' && seqCfg(run.stage).sky){
    /* SKY LAUNCH: open sky instead of a liquid bed, with the parallax cloud deck thickening as
       the climb builds. No ground to tile up here. */
    const sky=clamp(drawLaunch._sky||0,0,1);
    ctx.save();
    ctx.fillStyle=seqCfg(run.stage).fill; ctx.fillRect(0,0,VW,VH);
    if(X && X.rdy('nsky6_par')){
      const im=X.get('nsky6_par');
      const dh=VW*(im.naturalHeight/im.naturalWidth);
      const layers=1+Math.round(sky*3);                 /* more cloud passes the higher we get */
      for(let L=0; L<layers; L++){
        ctx.globalAlpha=0.30+0.16*L;
        let off=((dist*(0.5+L*0.35))%dh); if(off<0) off+=dh;
        for(let yy=off-dh; yy<VH; yy+=dh) ctx.drawImage(im,0,yy,VW,dh);
      }
    }
    ctx.restore();
  } else {
    _region(_liquidFrame(), SEG_B2, SEG_B3, dist, (run.stage===3?'rgba(150,222,255,0.42)':null), (run.stage===2?'#241008':'#0a1505'));
  }
  // TERRAIN region removed per Mike — runway extends straight up to the liquid
  /* RUNWAY: stages 4 and 7 have authored 800x1000 plates (approach / main / exit). Everything
     else has no runway art at all, so it keeps the legacy strip. Never invent a runway. */
  const _rwMain=(typeof seqRunway==='function')?seqRunway(run.stage,'run'):null;
  const _rwApp =(typeof seqRunway==='function')?seqRunway(run.stage,'app'):null;
  /* CONNECTOR: entering stage N>1, the plate that bridges N-1 -> N scrolls through FIRST, below
     the runway. 3>4, 4>5, 6>7 and 7>8 were drawn; 1>2, 2>3 and 5>6 never were, so those stages
     simply open on their own bed instead of a bridge that does not exist. */
  const _con=(typeof seqConnector==='function' && run.stage>1) ? seqConnector(run.stage-1, run.stage) : null;
  if(_con && X) _region(X.get(_con), -2000, -600, dist, null, null);
  if(_rwMain && X){
    /* FULL RUNWAY SEQUENCE, in the order you actually fly it:
         start-approach (behind you, where you rolled from) -> main-runway (tiled, the roll) ->
         runway-exit (the lip you leave the ground on, right before the bed opens up).
       Stages 4 and 7 have all three; stage 1's legacy strip only has the main part. */
    const _rwExit=(typeof seqRunway==='function')?seqRunway(run.stage,'exit'):null;
    if(_rwApp) _region(X.get(_rwApp), -1000, 0, dist, null, null);
    _region(X.get(_rwMain), 0, SEG_B1, dist, null, (typeof seqCfg==='function'?seqCfg(run.stage).fill:'#14140f'));
    if(_rwExit) _region(X.get(_rwExit), SEG_B1, SEG_B2, dist, null, null);
    else _region(X.get(_rwMain), SEG_B1, SEG_B2, dist, null, null);
  } else {
    _region(X&&X.get('runway'), 0, SEG_B2, dist, null, '#14140f');
  }
  if(X){ const pad=X.get('landingpad'); if(pad&&pad.complete&&pad.naturalWidth){    /* pad drawn once at the very start */
    const dw=VW, dh=dw*(pad.naturalHeight/pad.naturalWidth), st=VH*ANCHORY-(dh-dist);
    if(st<VH && st+dh>0) ctx.drawImage(pad,0,Math.round(st),dw,Math.ceil(dh)); } }
  ctx.restore();
  _speedLines((run.stage===5?0.25:0.10)+(run.stage===5?1.3:0.85)*nrm);
  /* ---- sfx cues ---- */
  /* NO LAUNCH OR THRUSTER CUES (drop 0801fd). Mike: "no more thruster or launch
     sounds." Both were one-shots fired from the transition; the music carries it.
     (drawLaunch lives in patches.js, not gamecode.js - my first patch went into
     the dead copy and did nothing, same as the HUD in 0801ej.) */
  /* ---- ship: launches off the pad, pulls up over the run, settles into the level ---- */
  let shipY, suf='', shipH=62;             // plain hull; the thruster is drawn live (drop 0808g)
  if(ph==='run'){ shipY=lerp(VH*0.66, VH*0.42, _ease(clamp(dist/SEG_B1,0,1)))+Math.sin(t*3)*3;
    if(_space){ // lifting off: the ship scales up as it rockets toward space
      const lift=_ease(clamp(dist/(SEG_B3),0,1)); shipH=lerp(62, 128, lift); shipY=lerp(VH*0.66, VH*0.30, lift); }
  }
  else if(ph==='brake'){ shipY=lerp(VH*0.42, VH*0.60, _ease(clamp(drawLaunch._pt/2.0,0,1))); if(_space) shipH=lerp(128,62,_ease(clamp(drawLaunch._pt/2.0,0,1))); }
  else { shipY=VH*0.60; suf=''; }  // 3-2-1-GO: hold the ship still, no bob/drift
  drawShipSprite(VW/2, shipY, shipH, suf);
  /* THE PILOT'S OWN ANIMATED PLUME (drop 0801fd). Mike: "start using our pilots
     with the animated thruster during the stage transitions, no more static
     images. this applies for all 9 of them."

     nthp_<pilot>_0..3 is a four-frame plume authored for every one of the nine
     and already in PRELOAD, but it was only ever drawn during PLAY - the
     transition showed the ship with nothing behind it. */
  if(typeof XART!=='undefined'){
    const _tk='nthp_'+(run.pilot||'cole')+'_'+(((performance.now()/70)|0)%4);
    if(XART.rdy(_tk)){
      const im=XART.get(_tk);
      /* ⚠ THE SAME BUG AS THE PLAY DRAW, WEARING A DIFFERENT HAT (drop 0808c). This one keeps
         each frame's aspect — but it scales EVERY frame to the same _th, so the 81x102 frame and
         the 170x192 frame come out the same height and the pulse the artist built into the reel
         is flattened out of it. The transition showed a thruster that never changed.

         Scaled against the reel's LARGEST frame instead, so the small frames draw small. */
      let _refH=0;
      for(let _q=0;_q<4;_q++){
        const _r=XART.rdy('nthp_'+(run.pilot||'cole')+'_'+_q) && XART.get('nthp_'+(run.pilot||'cole')+'_'+_q);
        if(_r && _r.naturalHeight>_refH) _refH=_r.naturalHeight;
      }
      if(!_refH) _refH=im.naturalHeight||1;
      const _k=(shipH*1.15)/_refH;
      const _th=im.naturalHeight*_k, _tw=im.naturalWidth*_k;
      ctx.save();
      ctx.globalCompositeOperation='lighter';
      ctx.globalAlpha=(ph==='run')?0.95:0.55;      // full burn on the run, banked on the brake
      ctx.drawImage(im, VW/2-_tw/2, shipY+shipH*0.30, _tw, _th);
      ctx.restore();
    }
  }
  /* ---- GET READY 3-2-1 -> GO ---- */
  if(ph==='cd'){
    const ct=drawLaunch._pt;
    if(ct<3.0){
      const num=3-Math.floor(ct);
      if(drawLaunch._num!==num){ drawLaunch._num=num; if(Audio.SFX.getready)Audio.SFX.getready(); }
      if(art){ stageText(art,'GET READY',VW/2,VH*0.34,20,null,null,1,0.12);
        const f=ct-Math.floor(ct),pop=1+(1-f)*0.5; stageText(art,String(num),VW/2,VH*0.52,52*pop,null,null,1,0.10); }
      else {
        /* ⚠ THE FALLBACK WAS THE BUG THE PLAYER SAW (drop 0807e). When the stage font is not
           decoded yet this branch ran, and it drew ONLY the number — no GET READY, plain BOFmil,
           flat orange. That is exactly the bare "3" Mike photographed and mistook for the
           game-over continue counter, because that is what it looks like.

           A fallback that drops half the content is not a fallback. This one carries the same
           two lines and the same pop, so a slow font decode costs polish rather than meaning. */
        ctx.save(); ctx.textAlign='center';
        const f=ct-Math.floor(ct), pop=1+(1-f)*0.5;
        ctx.font='bold 20px "BOFmil", monospace';
        ctx.fillStyle='#9fb4d0'; ctx.fillText('GET READY', VW/2, VH*0.34);
        ctx.font='bold '+Math.round(52*pop)+'px "BOFmil", monospace';
        ctx.lineWidth=4; ctx.strokeStyle='#241a06'; ctx.strokeText(String(num), VW/2, VH*0.54);
        ctx.fillStyle='#ffd36b'; ctx.fillText(String(num), VW/2, VH*0.54);
        ctx.restore();
      }
    } else {
      if(!drawLaunch._go){ drawLaunch._go=true; if(Audio.SFX.go)Audio.SFX.go(); shake=Math.max(shake,5); }
      const f=clamp((ct-3.0)/0.85,0,1),pop=1+(1-f)*0.8;
      if(typeof msgText==='function'){ msgText('GO!',VW/2,VH*0.46,64*pop,'#ffffff',0,1,0.08); }
      else { ctx.textAlign='center'; ctx.fillStyle='#ffffff'; ctx.font='bold 60px "BOFmil", monospace'; ctx.fillText('GO!',VW/2,VH*0.5); }
      if(ct>=3.85){ finishLaunch(); }
    }
  }
  /* NON-SKIPPABLE: no skip input */
}
function finishLaunch(){ drawLaunch._eng=false; drawLaunch._thr=false;
  if(!drawLaunch._mus) Audio.startMusic((curStage&&curStage.music)||'stage'); drawLaunch._mus=false;
  setState(GS.PLAY);
}

function metalBanner(){
  ctx.fillStyle='#1c2614'; ctx.fillRect(-150,-40,300,80);
  ctx.strokeStyle='#3a5a28'; ctx.lineWidth=3; ctx.strokeRect(-148,-38,296,76);
  ctx.fillStyle='#2a3a1c';
  for(let i=-140;i<140;i+=20) px(i,-40,4,80,'#22301a');
  // palm flair
  ctx.fillStyle='#2f7a1f'; for(const sx of [-150,150]){ ctx.save();ctx.translate(sx,-30);
    for(let a=0;a<5;a++){const an=Math.PI+a*0.4-0.8; ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(an)*18,Math.sin(an)*14);ctx.lineTo(Math.cos(an+0.2)*16,Math.sin(an+0.2)*12);ctx.fill();} ctx.restore(); }
}
function easeOut(t){ return 1-Math.pow(1-t,3); }

/* WORLD render during play */
function drawWorld(dt){

  ctx.save();
  updateCamX();
  if(worldWidth()>VW){ ctx.translate(-camX, 0); }   // horizontal camera scroll for the 800px jungle level (live check: cached WORLD_W must never shift non-scroll stages)
  if(shake>0){ ctx.translate(rnd(-shake,shake),rnd(-shake,shake)); }
  drawBG(dt);
  if(run.stage===6 && typeof l6CloudsDraw==='function'){ l6CloudsUpdate(dt); l6CloudsDraw(false); if(typeof l6ObjsDraw==='function') l6ObjsDraw(); }   // far decks + storm scenery behind everything
  if(run.stage===5 && typeof l5FieldDraw==='function'){ l5FieldUpdate(dt); l5FieldDraw(false); }   // far orbital hardware + asteroid belt
  drawPowerups();
  if(typeof drawScenery==='function') drawScenery();
  /* DAMAGE STATES RIDE ON TOP OF THE SPRITE (drop 0807f). Hooked at the loop rather than inside
     drawEnemy, because that function has a dozen early returns for sandtanks, drones, L6
     fighters and the zap flash — a unit taking any of those paths would silently never smoke. */
  for(const e of enemies){ drawEnemy(e); try{ drawEnemyDamage(e, _lastDt||1/60); }catch(_de){} }
  try{ drawSmokeRings(); }catch(_sr){}
  try{ drawNavalFlashes(); }catch(_nf){}
  /* NO FADE-OUTS (drop 0806j). Mike: "stop fading them out. there should be no fade out effects
     for any enemies, mini bosses, bosses, or effects, period ... we have sprites and effects for
     a reason."

     This re-drew the dead WRECK for a further half second at declining alpha, on top of the
     explosion. So every kill ended with a ghost of the unit hanging in the smoke instead of the
     death effect doing its job. The list is still ticked and still expires — only the ghost draw
     is gone, so nothing else that reads fadeOuts changes behaviour. */
  if(boss) drawBoss();
  if(boss && boss._morphT!=null && typeof vileMorphDraw==='function') vileMorphDraw(boss);
  if(subBoss) drawSubBoss();
  if(typeof speedPadsDraw==='function') speedPadsDraw();   // boost pads sit on the deck, under the craft
  if(typeof l6GMDraw==='function') l6GMDraw();   // giant missiles ride over the fight
  if(run.stage===5 && typeof l5RocksDraw==='function') l5RocksDraw();   // asteroids share the play plane
  if(typeof orbBeamsDraw==='function') orbBeamsDraw();   // orbital laser beams over the field
  if(typeof helixBurstsDraw==='function') helixBurstsDraw();   // Maverick's terminal bloom
  if(run.stage===6 && typeof l6CloudsDraw==='function') l6CloudsDraw(true);   // near decks sweep OVER the fight
  if(run.stage===5 && typeof l5FieldDraw==='function') l5FieldDraw(true);     // near debris sweeps OVER the fight
  if(run.stage===6 && typeof l6WeatherDraw==='function') l6WeatherDraw();      // rain/squall/lightning sheet over the whole field
  if(typeof wfxUpdate==='function'){ wfxUpdate(dt); wfxDraw(); }   // WEATHER FX: L2 firewave / L3 snow / L6 bolts
  if(typeof allyUpdate==='function') allyUpdate(dt);                 // spared-rival wingman
  if(typeof allyDraw==='function') allyDraw();
  drawZaps();
  drawNukeImpacts();
  drawSmokeTrails(); drawRetina(); drawPlayerLocks();
  drawWarning();
  drawMissileRushHUD();
  drawSpecialHUD();
  /* RADIO. Drawn last so it sits over the HUD, ducked automatically while a boss is alive so a
     line never competes with a bullet pattern (delivery rule 5). */
  if(typeof storyTick==='function'){ storyTick(1/60); if(bossActive) storyDuck(); storyDraw(); }
  /* the BOSS WARNING card rides the alert, then clears itself */
  if(_bossCard){ _bossCard.t+=1/60;
    if(_bossCard.t>3.2) _bossCard=null;
    else if(typeof arcDraw==='function') arcDraw(_bossCard.lines, VW/2, VH*0.30, 13,
      clamp(_bossCard.t/1.2,0,1), '#ff6b4a'); }
  drawBullets();
  drawFalvaAura();     // pink glow burning off the hull — UNDER the ship
  if(typeof drawFalvaCharge==='function') drawFalvaCharge();   // Falva: charge aura + roller balls
  if(typeof drawColeCharge==='function') drawColeCharge();     // Cole: fusion-cannon charge (tier 8)
  /* MAVERICK: the same ring in neon green, sized to his charge. */
  if(specialActive('maverick') && special && special.mavCharging && typeof drawChargeRing==='function'){
    const mp=clamp((special.mavCharge||0)/(typeof MAV_FULL!=='undefined'?MAV_FULL:1),0,1.2);
    /* nchgM_ lived in fx/maverick, which Mike called useless — and it was: the flat-plate guard
       already measured it as an 84% single-colour plate and SKIPPED the ring draw every time. The
       call is removed rather than repointed, because nothing was ever appearing. */
    if(false) drawChargeRing('nchgM_', player.x, player.y, Math.max(46, player.w*2.6*(0.72+0.28*Math.min(mp,1))), mp, 0.55+0.45*Math.min(mp,1));
  }
  drawMavCoilUnder();  // Maverick: helix strand passing BEHIND the hull
  if(typeof thawDraw==='function') thawDraw();       // stage-3 thaw panel (drop 0806d)
  if(typeof dkDraw==='function') dkDraw();            // shells, decals + muzzle blast (drop 0805w)
  if(typeof sonicDraw==='function') sonicDraw();      // distortion sits under the ship (drop 0805i)
  drawPlayer();
  if(typeof lzMountDraw==='function') lzMountDraw();  // pack: "above ship body"
  drawFalvaOrbs();     // orbs swirling AROUND her + the ball forming at the nose — OVER the ship
  drawMavCoilOver();   // Maverick: the other strand IN FRONT — together they wrap the ship
  drawRollers(); drawFalvaBalls();
  drawShards();
  drawEffects();
  /* THE DEATH FX WERE DRAWN FROM A DEAD FUNCTION (drop 0801kc). Mike: "theres no
     shock rings for enemies, barely any debris".

     They were being CREATED correctly - measured, 1 ring and 10 debris per kill -
     but the draw call had landed inside drawRaceFight(), the race system Mike had
     me delete. Nothing calls it, so nothing was ever rendered. The rings and chunks
     existed in memory for their whole lifetime and were never once shown.

     Drawn here, in drawWorld's effects pass, where the rest of the world FX go. */
  try{ drawDeathDebris(); drawShockRings(); }catch(_dfe){}
  if(typeof freezerOrbDraw==='function') freezerOrbDraw();
  if(typeof freezerL3Draw==='function') freezerL3Draw();

  drawAtomBooms();
  drawBombs();
  ctx.restore();
  if(typeof drawIncomingWarnings==='function') drawIncomingWarnings();
  if(typeof drawCallout==='function') drawCallout(dt);
  if(typeof drawHUDOverlay==='function') drawHUDOverlay();
  // bomb white flash
  if(bombFlash>0){ ctx.fillStyle=`rgba(255,255,255,${clamp(bombFlash,0,0.8)})`; ctx.fillRect(0,0,VW,VH); }
  if(whiteBlast>0){ ctx.fillStyle=`rgba(255,255,255,${clamp(whiteBlast,0,1)})`; ctx.fillRect(0,0,VW,VH); }
  if(flashScreen>0){ ctx.fillStyle=`rgba(255,120,60,${clamp(flashScreen*0.5,0,0.5)})`; ctx.fillRect(0,0,VW,VH); }
  // CRT scanlines
  drawScanlines();
  // boss approaching banner
  if(boss && boss.enter){ ctx.fillStyle='#ff3a3a'; ctx.font='bold 16px "BOFmil", monospace'; ctx.textAlign='center';
    ctx.globalAlpha=0.6+0.4*Math.sin(performance.now()/120);
    ctx.fillText('!! '+boss.name+' !!',VW/2,VH*0.4); ctx.globalAlpha=1; }
  if(player.dead){ ctx.textAlign='center';
    if(run.lives>0) msgText('SHIP DESTROYED',VW/2,VH/2,26,null,0,1,0.10); }
}
/* EQUIPPED box is drawn OUT OF BOUNDS (page DOM, right of the game canvas) by updateEquippedBoxDom().
   The in-canvas draw was removed so it no longer sits inside the play area. */
function drawEquippedBox(){ /* moved to DOM overlay — see updateEquippedBoxDom */ }
function drawScanlines(){
  ctx.globalAlpha=0.08; ctx.fillStyle='#000';
  for(let y=0;y<VH;y+=2) ctx.fillRect(0,y,VW,1);
  ctx.globalAlpha=1;
}
function drawPaused(){
  ctx.fillStyle='rgba(0,0,0,0.6)'; ctx.fillRect(0,0,VW,VH);
  ctx.textAlign='center';
  msgText('PAUSED',VW/2,VH/2-10,30,null,0,1,0.12);
  ctx.fillStyle='#cfd6e0'; ctx.font='bold 10px "BOFmil", monospace';
  ctx.fillText('P = RESUME   ·   BACKSPACE = QUIT',VW/2,VH/2+20);
  if(Input.tap('p')){ setState(GS.PLAY); }
  if(Input.tap('backspace')){ Audio.stopMusic(); setState(GS.TITLE); menuIndex=0; Audio.startMusic('title'); }
}

